from pathlib import Path
import json, re, unicodedata, html
from hero_identity import hero_key

ROOT=Path('.')
LIVE=ROOT/'data/live-meta.json'
SCORE=ROOT/'data/meta-score.json'
CATALOG=ROOT/'data/hero-catalog.json'
OUT=ROOT/'explore/index.html'
SITEMAP=ROOT/'sitemap.xml'
BASE='https://juanggm04-ship-it.github.io/mlbb-meta-forge/'

for p in (LIVE,SCORE,CATALOG):
    if not p.exists(): raise RuntimeError(f'Meta Explorer dependency missing: {p}')
live=json.loads(LIVE.read_text(encoding='utf-8'))
score=json.loads(SCORE.read_text(encoding='utf-8'))
catalog=json.loads(CATALOG.read_text(encoding='utf-8'))
heroes=[h for h in live.get('heroes',[]) if h.get('name')]
scores={hero_key(h.get('name')):h for h in score.get('heroes',[]) if h.get('name')}
editorial={hero_key(h.get('name')) for h in catalog.get('heroes',[]) if h.get('name')}
if len(heroes)!=133: raise RuntimeError(f'Meta Explorer requires 133 live heroes, got {len(heroes)}')
if len(scores)!=133: raise RuntimeError(f'Meta Explorer requires 133 Meta Score rows, got {len(scores)}')

def slugify(name):
    s=''.join(c for c in unicodedata.normalize('NFD',str(name).lower()) if unicodedata.category(c)!='Mn')
    return re.sub(r'[^a-z0-9]+','-',s.replace('&','and')).strip('-')

rows=[]
for h in heroes:
    key=hero_key(h['name']); s=scores.get(key)
    if not s: raise RuntimeError(f'Meta Score missing for {h["name"]}')
    rows.append({
        'key':key,'name':h['name'],'slug':slugify(h['name']),
        'wr':h.get('wr'),'ban':h.get('ban'),'pick':h.get('pick'),
        'score':s.get('score'),'rank':s.get('rank'),'editorial':key in editorial
    })
rows.sort(key=lambda r:(r['rank'],r['name']))
if sum(1 for r in rows if r['editorial'])!=34: raise RuntimeError('Meta Explorer editorial coverage must be exactly 34')
data=json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
patch=html.escape(str(live.get('patch') or '—'))
source_updated=html.escape(str(live.get('source_updated') or 'no informada'))

metric_options=''.join(f'<option value="{k}">{label}</option>' for k,label in [('wr','Win rate'),('pick','Pick rate'),('ban','Ban rate'),('score','Meta Score')])
table_rows=''.join(
    f'<tr data-key="{html.escape(r["key"])}"><td>#{r["rank"]}</td><td><a href="../stats/heroes/{r["slug"]}/">{html.escape(r["name"])}</a>{" <small>Editorial</small>" if r["editorial"] else ""}</td><td>{r["wr"]:.2f}%</td><td>{r["pick"]:.2f}%</td><td>{r["ban"]:.2f}%</td><td>{r["score"]:.1f}</td></tr>' for r in rows
)
page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meta Explorer · mapa estadístico de 133 héroes | Meta Forge</title><meta name="description" content="Explora visualmente los 133 héroes live de MLBB por win rate, pick rate, ban rate y Meta Score."><link rel="canonical" href="{BASE}explore/"><style>
*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(circle at 12% 0,#15294b 0,transparent 30%),#070a12;color:#edf5ff;font-family:system-ui,-apple-system,Segoe UI,sans-serif}}a{{color:inherit}}main{{max-width:1180px;margin:auto;padding:24px 18px 70px}}.hero,.panel{{margin-top:16px;border:1px solid #263954;border-radius:24px;background:#0b1422;padding:20px}}.eyebrow{{color:#5de7ff;font-size:9px;font-weight:950;letter-spacing:.14em}}h1{{margin:7px 0;font-size:clamp(40px,8vw,72px);letter-spacing:-.06em}}h2{{margin:4px 0 8px}}p{{color:#8fa1bd;line-height:1.6}}.meta{{display:flex;gap:7px;flex-wrap:wrap;margin-top:13px}}.pill{{padding:6px 9px;border:1px solid #30445f;border-radius:999px;color:#a7b8cf;font-size:9px;font-weight:850}}.toolbar{{display:grid;grid-template-columns:1fr 180px 180px auto;gap:8px;margin-top:14px}}input,select,button{{border:1px solid #2b3e5a;border-radius:12px;background:#09121f;color:#edf5ff;padding:11px 12px;font:inherit}}button{{cursor:pointer;font-weight:850}}button:hover,button:focus-visible,input:focus-visible,select:focus-visible{{outline:2px solid #4de6ff;outline-offset:1px}}.plot-wrap{{position:relative;margin-top:14px;min-height:560px;border:1px solid #223550;border-radius:18px;background:linear-gradient(180deg,#08111d,#0a1320);overflow:hidden}}svg{{display:block;width:100%;height:auto;min-height:560px}}.axis{{stroke:#38506f;stroke-width:1}}.median{{stroke:#59708f;stroke-width:1;stroke-dasharray:6 7}}.tick{{fill:#7387a5;font-size:12px}}.quad{{fill:#536982;font-size:12px;font-weight:800;opacity:.8}}.dot{{cursor:pointer;stroke:#dcecff;stroke-width:1;transition:.15s opacity,.15s r,.15s stroke-width}}.dot.dim{{opacity:.12}}.dot.hit{{stroke:#fff;stroke-width:4}}.tooltip{{position:absolute;pointer-events:none;min-width:170px;padding:10px;border:1px solid #3b5475;border-radius:12px;background:#07101bea;box-shadow:0 12px 30px #0008;font-size:11px;z-index:4}}.tooltip b{{display:block;font-size:13px;margin-bottom:4px}}.detail{{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;margin-top:12px;padding:13px;border:1px solid #293d58;border-radius:15px;background:#09121f}}.detail-stats{{display:flex;gap:12px;flex-wrap:wrap;color:#9cafc8;font-size:10px}}.actions{{display:flex;gap:7px;flex-wrap:wrap}}.actions a{{text-decoration:none;padding:9px 11px;border:1px solid #344b6b;border-radius:10px;font-size:10px;font-weight:850}}.actions a.primary{{background:#52e6ff;color:#07101b;border-color:#52e6ff}}.legend{{display:flex;align-items:center;gap:9px;margin-top:11px;color:#7588a5;font-size:10px}}.gradient{{width:130px;height:8px;border-radius:99px;background:linear-gradient(90deg,hsl(210 70% 48%),hsl(280 80% 68%))}}details{{margin-top:16px}}summary{{cursor:pointer;font-weight:850}}.table-wrap{{overflow:auto;margin-top:12px;max-height:520px}}table{{width:100%;border-collapse:collapse;font-size:11px}}th,td{{padding:9px;border-bottom:1px solid #1f3047;text-align:left;white-space:nowrap}}th{{position:sticky;top:0;background:#0b1422;color:#91a4c1}}td small{{color:#ffd36c;margin-left:5px}}.disclaimer{{padding:11px;border-left:3px solid #566c8b;background:#09121f;color:#8193ae;font-size:10px;line-height:1.55}}@media(max-width:760px){{.toolbar{{grid-template-columns:1fr 1fr}}.toolbar input{{grid-column:1/-1}}.plot-wrap,svg{{min-height:480px}}.detail{{grid-template-columns:1fr}}}}@media(max-width:480px){{.toolbar{{grid-template-columns:1fr}}.toolbar input{{grid-column:auto}}}}
</style></head><body><main><a href="../">← Meta Forge</a><section class="hero"><span class="eyebrow">META EXPLORER · 133 LIVE</span><h1>El meta, como mapa.</h1><p>Compara visualmente señales estadísticas del roster completo. Cambia los ejes entre WR, pick, ban y Meta Score; busca un héroe y salta a su ficha o a Hero Compare.</p><div class="meta"><span class="pill">PATCH {patch}</span><span class="pill">133 HÉROES</span><span class="pill">34 CON CONTEXTO EDITORIAL</span><span class="pill">FUENTE MEDIDA {source_updated}</span></div></section><section class="panel"><div class="eyebrow">MAPA INTERACTIVO</div><div class="toolbar"><input id="exploreSearch" type="search" placeholder="Buscar héroe…" aria-label="Buscar héroe"><select id="xMetric" aria-label="Métrica del eje X">{metric_options}</select><select id="yMetric" aria-label="Métrica del eje Y">{metric_options}</select><button id="copyExplorer" type="button">Copiar vista</button></div><div id="plotWrap" class="plot-wrap"><svg id="metaPlot" viewBox="0 0 1000 620" role="group" aria-labelledby="plotTitle plotDesc"><title id="plotTitle">Mapa estadístico de héroes</title><desc id="plotDesc">Cada punto representa un héroe. Las líneas discontinuas representan la mediana de cada métrica seleccionada.</desc></svg><div id="exploreTooltip" class="tooltip" hidden></div></div><div class="legend"><span>Meta Score bajo</span><span class="gradient"></span><span>Meta Score alto</span></div><div id="exploreDetail" class="detail" aria-live="polite"><div><b>Selecciona un punto</b><div class="detail-stats">Verás sus cuatro señales y acciones rápidas.</div></div></div><p class="disclaimer"><b>Lectura descriptiva:</b> los cuadrantes solo indican si un valor está por encima o por debajo de la mediana del roster para los ejes elegidos. No son tiers, roles, counters ni probabilidades de victoria.</p></section><section class="panel"><details><summary>Tabla accesible · 133 héroes</summary><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Héroe</th><th>WR</th><th>Pick</th><th>Ban</th><th>Meta Score</th></tr></thead><tbody>{table_rows}</tbody></table></div></details></section></main><script id="meta-explorer-runtime">(()=>{{const HEROES={data};const metrics={{wr:{{label:'Win rate',unit:'%'}},pick:{{label:'Pick rate',unit:'%'}},ban:{{label:'Ban rate',unit:'%'}},score:{{label:'Meta Score',unit:''}}}};const svg=document.getElementById('metaPlot'),wrap=document.getElementById('plotWrap'),tip=document.getElementById('exploreTooltip'),search=document.getElementById('exploreSearch'),xs=document.getElementById('xMetric'),ys=document.getElementById('yMetric'),detail=document.getElementById('exploreDetail'),copy=document.getElementById('copyExplorer');xs.value='pick';ys.value='wr';let selected=null;const params=new URLSearchParams(location.search);if(metrics[params.get('x')])xs.value=params.get('x');if(metrics[params.get('y')])ys.value=params.get('y');search.value=params.get('q')||'';const initial=params.get('hero');function esc(s){{return String(s).replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}function median(values){{const a=values.filter(Number.isFinite).sort((a,b)=>a-b),n=a.length;return n%2?a[(n-1)/2]:(a[n/2-1]+a[n/2])/2}}function fmt(metric,v){{return Number.isFinite(v)?(metric==='score'?v.toFixed(1):v.toFixed(2)+'%'):'—'}}function state(){{const u=new URL(location.href);u.searchParams.set('x',xs.value);u.searchParams.set('y',ys.value);if(selected)u.searchParams.set('hero',selected.name);else u.searchParams.delete('hero');if(search.value.trim())u.searchParams.set('q',search.value.trim());else u.searchParams.delete('q');history.replaceState(null,'',u)}}function color(score){{const t=Math.max(0,Math.min(1,(score-20)/70));const h=210+70*t,l=48+20*t;return `hsl(${{h}} 78% ${{l}}%)`}}function renderDetail(h){{selected=h||null;if(!h){{detail.innerHTML='<div><b>Selecciona un punto</b><div class="detail-stats">Verás sus cuatro señales y acciones rápidas.</div></div>';state();return}}detail.innerHTML=`<div><b>#${{h.rank}} · ${{esc(h.name)}}</b><div class="detail-stats"><span>WR ${{fmt('wr',h.wr)}}</span><span>Pick ${{fmt('pick',h.pick)}}</span><span>Ban ${{fmt('ban',h.ban)}}</span><span>Meta Score ${{fmt('score',h.score)}}</span>${{h.editorial?'<span>Editorial disponible</span>':''}}</div></div><div class="actions"><a class="primary" href="../stats/heroes/${{h.slug}}/">Abrir ficha</a><a href="../compare/?a=${{encodeURIComponent(h.name)}}">Comparar</a></div>`;state()}}function draw(){{const x=xs.value,y=ys.value,W=1000,H=620,pad={{l:82,r:40,t:48,b:70}},plotW=W-pad.l-pad.r,plotH=H-pad.t-pad.b,xv=HEROES.map(h=>h[x]),yv=HEROES.map(h=>h[y]),xmin=Math.min(...xv),xmax=Math.max(...xv),ymin=Math.min(...yv),ymax=Math.max(...yv),xmed=median(xv),ymed=median(yv),xp=v=>pad.l+(v-xmin)/(xmax-xmin||1)*plotW,yp=v=>pad.t+plotH-(v-ymin)/(ymax-ymin||1)*plotH,q=search.value.trim().toLowerCase();tip.hidden=true;let markup=`<title id="plotTitle">Mapa estadístico de héroes</title><desc id="plotDesc">${{metrics[x].label}} frente a ${{metrics[y].label}}. Las líneas discontinuas indican las medianas del roster completo. Selecciona un punto con Enter o espacio.</desc><line class="axis" x1="${{pad.l}}" y1="${{pad.t+plotH}}" x2="${{pad.l+plotW}}" y2="${{pad.t+plotH}}"/><line class="axis" x1="${{pad.l}}" y1="${{pad.t}}" x2="${{pad.l}}" y2="${{pad.t+plotH}}"/><line class="median" x1="${{xp(xmed)}}" y1="${{pad.t}}" x2="${{xp(xmed)}}" y2="${{pad.t+plotH}}"/><line class="median" x1="${{pad.l}}" y1="${{yp(ymed)}}" x2="${{pad.l+plotW}}" y2="${{yp(ymed)}}"/><text class="tick" x="${{pad.l+plotW/2}}" y="600" text-anchor="middle">${{metrics[x].label}}</text><text class="tick" transform="translate(22 ${{pad.t+plotH/2}}) rotate(-90)" text-anchor="middle">${{metrics[y].label}}</text><text class="quad" x="${{pad.l+12}}" y="${{pad.t+20}}">X bajo · Y alto</text><text class="quad" x="${{pad.l+plotW-12}}" y="${{pad.t+20}}" text-anchor="end">X alto · Y alto</text><text class="quad" x="${{pad.l+12}}" y="${{pad.t+plotH-12}}">X bajo · Y bajo</text><text class="quad" x="${{pad.l+plotW-12}}" y="${{pad.t+plotH-12}}" text-anchor="end">X alto · Y bajo</text>`;for(let i=0;i<=4;i++){{const vx=xmin+(xmax-xmin)*i/4,vy=ymin+(ymax-ymin)*i/4;markup+=`<text class="tick" x="${{xp(vx)}}" y="${{pad.t+plotH+22}}" text-anchor="middle">${{fmt(x,vx)}}</text><text class="tick" x="${{pad.l-10}}" y="${{yp(vy)+4}}" text-anchor="end">${{fmt(y,vy)}}</text>`}}for(const h of HEROES){{const hit=!q||h.name.toLowerCase().includes(q),sel=selected&&selected.key===h.key;markup+=`<circle class="dot${{hit?'':' dim'}}${{sel?' hit':''}}" data-key="${{h.key}}" cx="${{xp(h[x])}}" cy="${{yp(h[y])}}" r="${{sel?8:5}}" fill="${{color(h.score)}}"><title>${{esc(h.name)}} · ${{metrics[x].label}} ${{fmt(x,h[x])}} · ${{metrics[y].label}} ${{fmt(y,h[y])}}</title></circle>`}}svg.innerHTML=markup;for(const el of svg.querySelectorAll('.dot')){{el.addEventListener('mouseenter',e=>{{const h=HEROES.find(v=>v.key===el.dataset.key);tip.innerHTML=`<b>${{esc(h.name)}}</b>${{metrics[x].label}}: ${{fmt(x,h[x])}}<br>${{metrics[y].label}}: ${{fmt(y,h[y])}}<br>Meta Score: ${{h.score.toFixed(1)}} · #${{h.rank}}`;tip.hidden=false;const rect=wrap.getBoundingClientRect(),er=el.getBoundingClientRect();tip.style.left=Math.min(rect.width-190,Math.max(8,er.left-rect.left+12))+'px';tip.style.top=Math.max(8,er.top-rect.top-18)+'px'}});el.addEventListener('mouseleave',()=>tip.hidden=true);el.addEventListener('click',()=>{{const h=HEROES.find(v=>v.key===el.dataset.key);renderDetail(h);for(const dot of svg.querySelectorAll('.dot')){{const active=dot.dataset.key===h.key;dot.classList.toggle('hit',active);dot.setAttribute('r',active?'8':'5');dot.setAttribute('aria-pressed',active?'true':'false')}}svg.dispatchEvent(new CustomEvent('mf:explorer-selected',{{detail:{{name:h.name}}}}))}})}}state()}}xs.addEventListener('change',draw);ys.addEventListener('change',draw);search.addEventListener('input',draw);copy.addEventListener('click',async()=>{{state();try{{await navigator.clipboard.writeText(location.href);copy.textContent='Vista copiada ✓';setTimeout(()=>copy.textContent='Copiar vista',1400)}}catch{{copy.textContent='Copia la URL del navegador'}}}});if(initial){{selected=HEROES.find(h=>h.name.toLowerCase()===initial.toLowerCase())||null;if(selected)renderDetail(selected)}}draw()}})();</script></body></html>'''
OUT.parent.mkdir(parents=True,exist_ok=True)
OUT.write_text(page,encoding='utf-8')
if SITEMAP.exists():
    text=SITEMAP.read_text(encoding='utf-8');url=BASE+'explore/'
    if url not in text:text=text.replace('</urlset>',f'<url><loc>{url}</loc></url></urlset>')
    SITEMAP.write_text(text,encoding='utf-8')
print(f'Meta Explorer generated: heroes={len(rows)}; editorial=34; metrics=wr/pick/ban/score; shareable=true; accessible_table=133')
